40	  /**
41	   * Returns the Helix instance id (e.g. {@code Server_localhost_1234}) for the given instance.
42	   */
43	  public static String getHelixInstanceId(Instance instance) {
44	    String prefix;
45	    switch (instance.getType()) {
46	      case CONTROLLER:
47	        prefix = Helix.PREFIX_OF_CONTROLLER_INSTANCE;
48	        break;
49	      case BROKER:
50	        prefix = Helix.PREFIX_OF_BROKER_INSTANCE;
51	        break;
52	      case SERVER:
53	        prefix = Helix.PREFIX_OF_SERVER_INSTANCE;
54	        break;
55	      case MINION:
56	        prefix = Helix.PREFIX_OF_MINION_INSTANCE;
57	        break;
58	      default:
59	        throw new IllegalStateException();
60	    }
61	    return prefix + instance.getHost() + "_" + instance.getPort();
62	  }
63	
64	  public static String getServerAdminEndpoint(InstanceConfig instanceConfig) {
65	    // Backward-compatible with legacy hostname of format 'Server_<hostname>'
66	    String hostname = instanceConfig.getHostName();
67	    if (hostname.startsWith(Helix.PREFIX_OF_SERVER_INSTANCE)) {
68	      hostname = hostname.substring(Helix.SERVER_INSTANCE_PREFIX_LENGTH);
69	    }
70	    return getServerAdminEndpoint(instanceConfig, hostname, CommonConstants.HTTP_PROTOCOL);
71	  }
72	
73	  public static String getServerAdminEndpoint(InstanceConfig instanceConfig, String hostname, String defaultProtocol) {
74	    String protocol = defaultProtocol;
75	    int port = CommonConstants.Server.DEFAULT_ADMIN_API_PORT;
76	    int adminPort = instanceConfig.getRecord().getIntField(Helix.Instance.ADMIN_PORT_KEY, -1);
77	    int adminHttpsPort = instanceConfig.getRecord().getIntField(Helix.Instance.ADMIN_HTTPS_PORT_KEY, -1);
78	    // NOTE: preference for insecure is sub-optimal, but required for incremental upgrade scenarios
79	    if (adminPort > 0) {
80	      protocol = CommonConstants.HTTP_PROTOCOL;
81	      port = adminPort;
82	    } else if (adminHttpsPort > 0) {
83	      protocol = CommonConstants.HTTPS_PROTOCOL;
84	      port = adminHttpsPort;
85	    }
86	    return String.format("%s://%s:%d", protocol, hostname, port);
87	  }
