89	  /**
90	   * Returns the Helix InstanceConfig for the given instance.
91	   */
92	  public static InstanceConfig toHelixInstanceConfig(Instance instance) {
93	    InstanceConfig instanceConfig = new InstanceConfig(getHelixInstanceId(instance));
94	    instanceConfig.setInstanceEnabled(true);
95	    updateHelixInstanceConfig(instanceConfig, instance);
96	    return instanceConfig;
97	  }
