99	  /**
100	   * Updates the Helix InstanceConfig with the given instance configuration. Leaves the fields not included in the
101	   * instance configuration unchanged.
102	   */
103	  public static void updateHelixInstanceConfig(InstanceConfig instanceConfig, Instance instance) {
104	    ZNRecord znRecord = instanceConfig.getRecord();
105	
106	    Map<String, String> simpleFields = znRecord.getSimpleFields();
107	    simpleFields.put(InstanceConfig.InstanceConfigProperty.HELIX_HOST.name(), instance.getHost());
108	    simpleFields.put(InstanceConfig.InstanceConfigProperty.HELIX_PORT.name(), Integer.toString(instance.getPort()));
109	    int grpcPort = instance.getGrpcPort();
110	    if (grpcPort > 0) {
111	      simpleFields.put(Helix.Instance.GRPC_PORT_KEY, Integer.toString(grpcPort));
112	    } else {
113	      simpleFields.remove(Helix.Instance.GRPC_PORT_KEY);
114	    }
115	    int adminPort = instance.getAdminPort();
116	    if (adminPort > 0) {
117	      simpleFields.put(Helix.Instance.ADMIN_PORT_KEY, Integer.toString(adminPort));
118	    } else {
119	      simpleFields.remove(Helix.Instance.ADMIN_PORT_KEY);
120	    }
121	    int queryServicePort = instance.getQueryServicePort();
122	    if (queryServicePort > 0) {
123	      simpleFields.put(Helix.Instance.MULTI_STAGE_QUERY_ENGINE_SERVICE_PORT_KEY, Integer.toString(queryServicePort));
124	    } else {
125	      simpleFields.remove(Helix.Instance.MULTI_STAGE_QUERY_ENGINE_SERVICE_PORT_KEY);
126	    }
127	    int queryMailboxPort = instance.getQueryMailboxPort();
128	    if (queryMailboxPort > 0) {
129	      simpleFields.put(Helix.Instance.MULTI_STAGE_QUERY_ENGINE_MAILBOX_PORT_KEY, Integer.toString(queryMailboxPort));
130	    } else {
131	      simpleFields.remove(Helix.Instance.MULTI_STAGE_QUERY_ENGINE_MAILBOX_PORT_KEY);
132	    }
133	    boolean queriesDisabled = instance.isQueriesDisabled();
134	    if (queriesDisabled) {
135	      simpleFields.put(Helix.QUERIES_DISABLED, Boolean.toString(true));
136	    } else {
137	      simpleFields.remove(Helix.QUERIES_DISABLED);
138	    }
139	
140	    Map<String, List<String>> listFields = znRecord.getListFields();
141	    List<String> tags = instance.getTags();
142	    String tagsKey = InstanceConfig.InstanceConfigProperty.TAG_LIST.name();
143	    if (CollectionUtils.isNotEmpty(tags)) {
144	      listFields.put(tagsKey, tags);
145	    } else {
146	      listFields.remove(tagsKey);
147	    }
148	
149	    Map<String, Map<String, String>> mapFields = znRecord.getMapFields();
150	    Map<String, Integer> pools = instance.getPools();
151	    if (MapUtils.isNotEmpty(pools)) {
152	      Map<String, String> mapValue = new TreeMap<>();
153	      for (Map.Entry<String, Integer> entry : pools.entrySet()) {
154	        mapValue.put(entry.getKey(), entry.getValue().toString());
155	      }
156	      mapFields.put(POOL_KEY, mapValue);
157	    } else {
158	      mapFields.remove(POOL_KEY);
159	    }
160	  }
