package org.apache.pinot.spi.config.instance;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import org.apache.pinot.spi.exception.ConfigValidationException;


/**
 * Static registry for instance configuration validators. External code can register custom
 * {@link InstanceConfigValidator}s that are invoked (in registration order) before an instance
 * configuration is committed to the cluster.
 *
 * <p>This class is thread-safe: registration and validation may happen concurrently.
 */
public class InstanceConfigValidatorRegistry {
  private InstanceConfigValidatorRegistry() {
  }

  /**
   * Validator invoked before an {@link Instance} configuration is persisted. Implementations throw
   * {@link ConfigValidationException} to reject the configuration.
   */
  @FunctionalInterface
  public interface InstanceConfigValidator {
    void validate(Instance instance)
        throws ConfigValidationException;
  }

  private static final List<InstanceConfigValidator> VALIDATORS = new CopyOnWriteArrayList<>();

  /**
   * Registers a validator to be invoked before an instance configuration is committed.
   */
  public static void register(InstanceConfigValidator validator) {
    VALIDATORS.add(validator);
  }

  /**
   * Invokes all registered validators in registration order. Short-circuits on the first validator
   * that throws {@link ConfigValidationException}, propagating that exception and skipping the rest.
   * No-op when no validators have been registered.
   */
  public static void validate(Instance instance)
      throws ConfigValidationException {
    for (InstanceConfigValidator validator : VALIDATORS) {
      validator.validate(instance);
    }
  }

  /**
   * Clears all registered validators.
   */
  public static void reset() {
    VALIDATORS.clear();
  }
}
