163	  /**
164	   * Converts a Helix {@link InstanceConfig} back into a pinot-spi {@link Instance}. This performs the reverse of
165	   * {@link #toHelixInstanceConfig(Instance)}.
166	   * <p>The {@link InstanceType} is determined from the instance id prefix ({@code Server_}, {@code Broker_},
167	   * {@code Controller_}, {@code Minion_}). Legacy server hostnames that include the {@code Server_} prefix are
168	   * stripped to the bare hostname. Optional ports (grpc, admin, query service, query mailbox) that are absent from
169	   * the config are returned as -1.
170	   *
171	   * @throws IllegalArgumentException if the instance id does not match any known instance type prefix
172	   */
173	  public static Instance toInstance(InstanceConfig instanceConfig) {
174	    String instanceId = instanceConfig.getInstanceName();
175	    InstanceType type;
176	    if (instanceId.startsWith(Helix.PREFIX_OF_SERVER_INSTANCE)) {
177	      type = InstanceType.SERVER;
178	    } else if (instanceId.startsWith(Helix.PREFIX_OF_BROKER_INSTANCE)) {
179	      type = InstanceType.BROKER;
180	    } else if (instanceId.startsWith(Helix.PREFIX_OF_CONTROLLER_INSTANCE)) {
181	      type = InstanceType.CONTROLLER;
182	    } else if (instanceId.startsWith(Helix.PREFIX_OF_MINION_INSTANCE)) {
183	      type = InstanceType.MINION;
184	    } else {
185	      throw new IllegalArgumentException("Unknown instance type for instance id: " + instanceId);
186	    }
187	
188	    // Backward-compatible with legacy server hostname of format 'Server_<hostname>'
189	    String host = instanceConfig.getHostName();
190	    if (type == InstanceType.SERVER && host != null && host.startsWith(Helix.PREFIX_OF_SERVER_INSTANCE)) {
191	      host = host.substring(Helix.SERVER_INSTANCE_PREFIX_LENGTH);
192	    }
193	    int port = Integer.parseInt(instanceConfig.getPort());
194	
195	    ZNRecord znRecord = instanceConfig.getRecord();
196	    int grpcPort = znRecord.getIntField(Helix.Instance.GRPC_PORT_KEY, Instance.NOT_SET_GRPC_PORT_VALUE);
197	    int adminPort = znRecord.getIntField(Helix.Instance.ADMIN_PORT_KEY, Instance.NOT_SET_ADMIN_PORT_VALUE);
198	    int queryServicePort = znRecord.getIntField(Helix.Instance.MULTI_STAGE_QUERY_ENGINE_SERVICE_PORT_KEY,
199	        Instance.NOT_SET_QUERY_SERVER_PORT_VALUE);
200	    int queryMailboxPort = znRecord.getIntField(Helix.Instance.MULTI_STAGE_QUERY_ENGINE_MAILBOX_PORT_KEY,
201	        Instance.NOT_SET_QUERY_MAILBOX_PORT_VALUE);
202	    boolean queriesDisabled = znRecord.getBooleanField(Helix.QUERIES_DISABLED, false);
203	
204	    List<String> tags = instanceConfig.getTags();
205	
206	    Map<String, Integer> pools = null;
207	    Map<String, String> poolMap = znRecord.getMapField(POOL_KEY);
208	    if (MapUtils.isNotEmpty(poolMap)) {
209	      pools = new TreeMap<>();
210	      for (Map.Entry<String, String> entry : poolMap.entrySet()) {
211	        pools.put(entry.getKey(), Integer.parseInt(entry.getValue()));
212	      }
213	    }
214	
215	    return new Instance(host, port, type, tags, pools, grpcPort, adminPort, queryServicePort, queryMailboxPort,
216	        queriesDisabled);

